const grid=document.querySelector('#storyGrid'),search=document.querySelector('#search'),region=document.querySelector('#region'),count=document.querySelector('#count');let stories=[];
function render(){const q=search.value.trim().toLocaleLowerCase('vi'),r=region.value;const list=stories.filter(s=>(!r||s.region===r)&&(!q||[s.title,s.country,s.type,s.excerpt].join(' ').toLocaleLowerCase('vi').includes(q)));count.textContent=`${list.length} truyện`;grid.innerHTML=list.length?list.map(s=>`<article class="card"><span class="tag">${DaKy.esc(s.country)} · ${DaKy.esc(s.type)}</span><h3>${DaKy.esc(s.title)}</h3><p>${DaKy.esc(s.excerpt)}</p><div class="card-footer"><span class="small">${DaKy.esc(s.region)}</span><a class="btn" href="story.html?slug=${encodeURIComponent(s.slug)}">Đọc truyện</a></div></article>`).join(''):'<div class="empty">Không tìm thấy truyện phù hợp.</div>'}
(async()=>{try{stories=await DaKy.getStories();[...new Set(stories.map(s=>s.region))].sort().forEach(x=>region.insertAdjacentHTML('beforeend',`<option>${DaKy.esc(x)}</option>`));render()}catch(e){grid.innerHTML='<div class="empty">Chưa thể tải dữ liệu. Vui lòng kiểm tra cấu hình.</div>'}})();search.addEventListener('input',render);region.addEventListener('change',render);
